SELECT CAST(result.c0 AS VARCHAR) AS "computation", CAST(result.c1 AS VARCHAR) AS "program", CAST(result.c2 AS VARCHAR) AS "epoch", CAST(result.c3 AS BIGINT) AS "target", CAST(result.c4 AS BIGINT) AS "covered", CAST(result.c5 AS BIGINT) AS "revision", CAST(result.c6 AS INTEGER) AS "busy", CAST(result.c7 AS BOOLEAN) AS "dirty", CAST(result.c8 AS BOOLEAN) AS "runnable" FROM (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, t.c3 AS c3, COALESCE(t.c9, CAST(0 AS BIGINT)) AS c4, COALESCE(t.c7, CAST(0 AS BIGINT)) AS c5, COALESCE(t.c8, CAST(0 AS INTEGER)) AS c6, (t.c3 > COALESCE(t.c9, CAST(0 AS BIGINT))) AS c7, ((t.c3 > COALESCE(t.c9, CAST(0 AS BIGINT))) AND (COALESCE(t.c8, CAST(0 AS INTEGER)) = CAST(0 AS INTEGER))) AS c8 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, r.c0 AS c4, r.c1 AS c5, r.c2 AS c6, r.c3 AS c7, r.c4 AS c8, r.c5 AS c9 FROM (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, CAST(MAX(t.c3) AS BIGINT) AS c3 FROM (SELECT "computation" AS c0, "program" AS c1, "epoch" AS c2, "snapshot" AS c3 FROM "applied") t GROUP BY t.c0, t.c1, t.c2) l LEFT JOIN (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, t.c3 AS c3, t.c4 AS c4, t.c5 AS c5 FROM (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, t.c3 AS c3, t.c4 AS c4, t.c5 AS c5 FROM (SELECT t.c4 AS c0, t.c5 AS c1, t.c6 AS c2, t.c7 AS c3, t.c8 AS c4, t.c9 AS c5, t.c0 AS c6, t.c1 AS c7, t.c2 AS c8, t.c3 AS c9 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, r.c0 AS c4, r.c1 AS c5, r.c2 AS c6, r.c3 AS c7, r.c4 AS c8, r.c5 AS c9 FROM (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, CAST(MAX(t.c3) AS BIGINT) AS c3 FROM (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, t.c3 AS c3 FROM (SELECT "computation" AS c0, "program" AS c1, "epoch" AS c2, "revision" AS c3, "busy" AS c4, "published_through" AS c5 FROM "lifecycle") t) t GROUP BY t.c0, t.c1, t.c2) l INNER JOIN (SELECT "computation" AS c0, "program" AS c1, "epoch" AS c2, "revision" AS c3, "busy" AS c4, "published_through" AS c5 FROM "lifecycle") r ON ((r.c0 = l.c0) AND (r.c1 = l.c1) AND (r.c2 = l.c2) AND (r.c3 = l.c3))) t) t) t GROUP BY t.c0, t.c1, t.c2, t.c3, t.c4, t.c5) r ON ((l.c0 = r.c0) AND (l.c1 = r.c1) AND (l.c2 = r.c2))) t) result;
